    { id:'bonds_depth', title:'Room beside the Line', act:2, description:'Help Nera trust a relief partner. Help Pax make a map that leaves space for another person.' },
    { id:'echo_depth', title:'Patterns from Below', act:2, description:'Study four shared patterns of shelter, growth, passage, and open sky. Each can teach without keeping a person.' },
    { id:'trials', title:'The Drift Court Trials', act:2, description:'Practice six fixed battles. Record weakness hits, Breaks, Support, items, and actions. A victory earns bronze; meeting goals improves the medal.' }
